import { NavigationProvider } from './context/NavigationContext';
import Dashboard from './pages/Dashboard/Dashboard';

function App() {
  return (
    <NavigationProvider>
      <div className={styles.appContainer}>
        <Sidebar />
        <div className={styles.content}>
          <Dashboard />
        </div>
      </div>
    </NavigationProvider>
  );
}
